package com.example.obliviondescent;

/**
 * Represents a single item generated by Gemini AI.
 * The type can be WEAPON, ARMOR or CONSUMABLE.
 * Stats map directly to the constructor of the corresponding game object.
 */
public class ShopItem {

    public enum ItemType { WEAPON, ARMOR, CONSUMABLE }

    // Common fields
    public String   name;
    public int      price;
    public String   colorHex;   // e.g. "#FF4400"
    public int      color;      // parsed from colorHex
    public String   description;
    public ItemType type;

    // Weapon fields (type == WEAPON)
    public int     damage;
    public float   range;
    public long    cooldown;
    public float   knockback;
    public boolean isProjectile;
    public String  rarity;      // "COMMON" / "RARE" / "EPIC" / "LEGENDARY"

    // Armor fields (type == ARMOR)
    public int    defense;
    public float  maxDurability;
    public String armorSlot;    // "HEAD" / "CHEST" / "LEGS" / "BOOTS"

    // Consumable fields (type == CONSUMABLE)
    public String effect;       // "heal" / "armor_restore"
    public boolean biomeTilted; // GameActivity.biomeGear has fitted it to its floor's biome
    public int    fullPrice;    // the shop's sale item: its price before the discount (0 = not on sale)
    public int    effectValue;  // amount to heal/restore

    /**
     * Converts this ShopItem to a Weapon object.
     * Valid only when type == WEAPON.
     * @return the corresponding Weapon object
     */
    public Weapon toWeapon() {
        Weapon.Rarity r;
        try {
            r = Weapon.Rarity.valueOf(rarity.toUpperCase());
        } catch (Exception e) {
            r = Weapon.Rarity.COMMON;
        }
        return new Weapon(name, damage, range, cooldown, r, color, knockback, isProjectile);
    }

    /**
     * Converts this ShopItem to an Armor object.
     * Valid only when type == ARMOR.
     * @return the corresponding Armor object
     */
    public Armor toArmor() {
        Armor.Rarity r;
        try {
            r = Armor.Rarity.valueOf(rarity.toUpperCase());
        } catch (Exception e) {
            r = Armor.Rarity.COMMON;
        }
        Armor.Slot slot;
        try {
            slot = Armor.Slot.valueOf(armorSlot.toUpperCase());
        } catch (Exception e) {
            slot = Armor.Slot.CHEST;
        }
        return new Armor(name, defense, maxDurability, r, color, slot);
    }
}